insert into public.nutrition_items (id, name, aka, category, serving, kcal, protein, carbs, fat, price_ghs, tips) values
  ('eggs', 'Eggs', null, 'protein', '2 large eggs', 143, 12.6, 0.7, 9.5, 5.0, array['One of the cheapest complete proteins you can buy.', 'Boil a batch for quick breakfasts and snacks.', 'Eat the yolk — it carries half the protein and most of the vitamins.']::text[]),
  ('beans_red_red', 'Red-red', 'Black-eyed bean stew', 'protein', '1 bowl (250 g)', 350, 13.0, 40.0, 15.0, 8.0, array['Beans give protein and fibre that keep you full.', 'Go lighter on the palm oil when cutting body fat.', 'Add an egg or sardines to push the protein past 20 g.']::text[]),
  ('sardines', 'Sardines', null, 'protein', '1 tin (≈ 90 g drained)', 190, 21.0, 0.0, 11.0, 15.0, array['Protein plus omega-3 fats in one tin.', 'Eat the soft bones for extra calcium.', 'Great with kenkey, bread or gari.']::text[]),
  ('tuna', 'Tuna', null, 'protein', '1 tin (≈ 110 g drained)', 150, 27.0, 0.0, 4.0, 22.0, array['Choose tuna in water or brine for fewer calories.', 'Mix with tomato and onion for a quick salad.']::text[]),
  ('chicken', 'Chicken', null, 'protein', 'Thigh + drumstick (150 g)', 330, 36.0, 0.0, 20.0, 20.0, array['Remove the skin to cut the fat by about a third.', 'Grill or boil instead of deep-frying.']::text[]),
  ('tilapia', 'Tilapia', null, 'protein', '1 medium fish (150 g edible)', 190, 39.0, 0.0, 4.0, 35.0, array['Very lean, very high protein.', 'Grilled tilapia with banku is a strong post-workout meal.']::text[]),
  ('mackerel', 'Mackerel', '"Salmon" / smoked fish', 'protein', '100 g', 250, 22.0, 0.0, 17.0, 15.0, array['Rich in healthy fats.', 'Smoked fish adds protein to any stew for little money.']::text[]),
  ('milk', 'Milk', null, 'protein', '1 cup (250 ml)', 150, 8.0, 12.0, 8.0, 6.0, array['Powdered milk is often the cheapest per gram of protein.', 'Add to oats or tea for easy protein.']::text[]),
  ('wagashi', 'Wagashi', 'Wagashie cheese', 'protein', '100 g', 260, 20.0, 3.0, 18.0, 10.0, array['A local cheese that is high in protein.', 'Grill or add to stew instead of deep-frying.']::text[]),
  ('soya_chunks', 'Soya chunks', null, 'protein', '50 g dry', 170, 26.0, 16.0, 0.5, 4.0, array['One of the best protein-per-cedi foods.', 'Soak, squeeze and cook in stew like meat.']::text[]),
  ('rice', 'Rice', null, 'carbs', '1 cup cooked (160 g)', 205, 4.3, 45.0, 0.4, 4.0, array['Match the portion to your activity — bigger on training days.', 'Pair with beans for more protein.']::text[]),
  ('oats', 'Oats', null, 'carbs', '40 g dry', 150, 5.0, 27.0, 2.5, 3.0, array['Slow energy that keeps you full.', 'Cook with milk and top with groundnuts for a protein breakfast.']::text[]),
  ('plantain', 'Plantain', null, 'carbs', '1 medium, boiled (180 g)', 210, 2.0, 55.0, 0.3, 5.0, array['Boiled or roasted plantain has far fewer calories than fried.', 'Unripe plantain keeps you fuller.']::text[]),
