insert into public.challenges (id, title, tagline, description, daily_prompt, check_type, days_required, daily_target, protein_target, price_limit_ghs, tips) values
  ('protein_20', 'GH₵20 Protein Challenge', 'Big protein, small budget', 'Build a protein-focused meal with at least 25 g of protein for GH₵20 or less, using everyday foods. Do it on 7 different days.', 'Build today''s GH₵20 meal', 'mealBuilder', 7, 1, 25.0, 20.0, array['Eggs, sardines, beans, soya chunks and groundnuts give the most protein per cedi.', 'Combine a cheap carb (gari, kenkey, rice) with one strong protein.', 'Set your local prices in the food database so the totals match your market.']::text[]),
  ('water_7', '7-Day Water Challenge', 'Build a hydration habit', 'Drink your daily water target on 7 days. Tap a glass each time you finish one.', 'Glasses of water today', 'counter', 7, 8, 0.0, 0.0, array['Keep a filled bottle where you can see it.', 'Drink a glass as soon as you wake up.', 'Drink more on hot days and training days.']::text[]),
  ('breakfast_7', '7-Day Breakfast Challenge', 'Start the day strong', 'Eat a breakfast with a protein source (eggs, milk, groundnuts, beans…) on 7 days.', 'Did you eat a protein breakfast today?', 'yesNo', 7, 1, 0.0, 0.0, array['Boil eggs the night before.', 'Oats with milk and groundnuts takes 5 minutes.', 'Koko with groundnuts and an egg beats koko alone.']::text[]),
  ('no_soda_7', 'No Soft Drink Challenge', 'Cut the sugar', 'Go 7 days without sugary soft drinks or sweetened juice.', 'Soft-drink free today?', 'yesNo', 7, 1, 0.0, 0.0, array['A single 500 ml soft drink can hold more than 10 teaspoons of sugar.', 'Swap for water with lime, or sobolo without added sugar.', 'Check the label on "juice" drinks too.']::text[])
on conflict (id) do update set
  title = excluded.title,
  tagline = excluded.tagline,
  description = excluded.description,
  daily_prompt = excluded.daily_prompt,
  check_type = excluded.check_type,
  days_required = excluded.days_required,
  daily_target = excluded.daily_target,
  protein_target = excluded.protein_target,
  price_limit_ghs = excluded.price_limit_ghs,
  tips = excluded.tips;

